async def messages_handler(request):
    """REST endpoint to retrieve message history."""
    try:
        limit = int(request.query.get("limit", "50"))
        offset = int(request.query.get("offset", "0"))

        # Clamp values
        limit = max(1, min(limit, 1000))
        offset = max(0, offset)

        messages = get_messages(limit, offset)
        return web.json_response({
            "messages": messages,
            "limit": limit,
            "offset": offset,
            "count": len(messages),
        })
    except ValueError:
        return web.json_response({"error": "invalid limit or offset"}, status=400)


async def history_handler(request):
    """REST endpoint to retrieve channel message history with optional time range."""
    try:
        channel = request.query.get("channel")
        if not channel:
            return web.json_response({"error": "channel parameter required"}, status=400)

        since = request.query.get("since")
        limit = int(request.query.get("limit", "50"))

        # Clamp limit
        limit = max(1, min(limit, 1000))

        messages, has_more = get_channel_history(channel, since, limit)
        return web.json_response({
            "channel": channel,
            "messages": messages,
            "limit": limit,
            "count": len(messages),
            "has_more": has_more,
        })
    except ValueError:
        return web.json_response({"error": "invalid parameters"}, status=400)

